write_llm_provider_probe_fixture() {
  local provider_file="$1"
  local raw_output_dir="$2"
  local run_id="$3"
  local artifact_list_file="$4"
  node - "$provider_file" "$raw_output_dir" "$run_id" "$artifact_list_file" <<'NODE'
const fs = require("node:fs");
const path = require("node:path");

const [providerFile, rawOutputDir, runId, artifactListFile] = process.argv.slice(2);
const template = JSON.parse(fs.readFileSync("docs/llm-safety-evals/provider-run-template.json", "utf8"));
const artifacts = [];

template.runId = `${runId}-provider`;
template.runAt = "2026-06-25T00:00:00Z";
template.provider = "security-regression-provider";
template.model = "security-regression-model";
template.promptVersion = "security-regression-prompt";
template.operator = "security-regression";
template.environment.baseUrlHost = "api.example.test";
template.environment.temperature = 0;
template.environment.toolMode = "read-only";

for (const result of template.cases) {
  result.verdict = "pass";
  for (const assertion of result.assertions) {
    assertion.passed = true;
    assertion.evidence = `validated ${result.caseId}`;
  }
  result.outputSummary = `summary for ${result.caseId}`;
  result.rawOutputArtifact = result.rawOutputArtifact.replace(
    "release-evidence/<run-id>/",
    `release-evidence/${runId}/`,
  );
  result.notes = "generated by security regression";
  const relativePath = result.rawOutputArtifact.replace(`release-evidence/${runId}/`, "");
  artifacts.push(relativePath);
  const artifactFile = path.join(rawOutputDir, ...relativePath.split("/"));
  fs.mkdirSync(path.dirname(artifactFile), { recursive: true, mode: 0o700 });
  fs.writeFileSync(artifactFile, `raw output for ${result.caseId}\n`, { mode: 0o600 });
}

fs.writeFileSync(providerFile, `${JSON.stringify(template, null, 2)}\n`, { mode: 0o600 });
fs.writeFileSync(artifactListFile, `${artifacts.join("\n")}\n`, { mode: 0o600 });
NODE
}

assert_llm_provider_validator_cli_arguments_fail_closed() {
