    || fail "could not create LLM provider validator CLI probe temp dir"
  chmod 0700 "$tmp_dir" || failure="could not harden LLM provider validator CLI probe temp dir"
  output_file="$tmp_dir/output.txt"

  cleanup_llm_provider_cli_probe() {
    rm -rf "$tmp_dir"
  }

  if [[ -z "$failure" ]]; then
    if run_security_node scripts/validate-llm-provider-run.mjs \
      docs/llm-safety-evals/provider-run-template.json \
      docs/llm-safety-evals/prompt-injection-cases.json \
