      failure="LLM provider run validator must reject --run-id without a value"
    elif ! rg -q -- '--run-id requires a non-empty release evidence run id' "$output_file"; then
      cat "$output_file" >&2
      failure="LLM provider run validator must explain missing --run-id value"
    fi
  fi
  if [[ -z "$failure" ]]; then
    if run_security_node scripts/validate-llm-provider-run.mjs \
      docs/llm-safety-evals/provider-run-template.json \
      docs/llm-safety-evals/prompt-injection-cases.json \
      docs/llm-safety-evals/output-quality-cases.json \
      --run-idd probe > "$output_file" 2>&1; then
      cat "$output_file" >&2
      failure="LLM provider run validator must reject unknown options"
    elif ! rg -q -- 'unknown option: --run-idd' "$output_file"; then
      cat "$output_file" >&2
      failure="LLM provider run validator must explain unknown options"
    fi
  fi
  if [[ -z "$failure" ]]; then
    if run_security_node scripts/validate-llm-provider-run.mjs \
      docs/llm-safety-evals/provider-run-template.json \
      docs/llm-safety-evals/prompt-injection-cases.json \
      docs/llm-safety-evals/output-quality-cases.json \
      extra-positional > "$output_file" 2>&1; then
      cat "$output_file" >&2
      failure="LLM provider run validator must reject extra positional arguments"
    elif ! rg -q -- 'usage: validate-llm-provider-run.mjs' "$output_file"; then
      cat "$output_file" >&2
      failure="LLM provider run validator must explain positional argument usage"
    fi
  fi

  cleanup_llm_provider_cli_probe
  [[ -z "$failure" ]] || fail "$failure"
}

assert_llm_provider_eval_generator_writes_private_schema_without_secrets() {
  local tmp_dir
  local output_file
  local raw_output_dir
  local stdout_file
  local artifacts_file
  local run_id
  local secret_value
  local exit_code
  local artifact_path
  local relative_path
  local failure=""

  tmp_dir="$(mktemp -d "${TMPDIR:-/tmp}/sourcelens-llm-provider-eval-probe.XXXXXX")" \
    || fail "could not create LLM provider eval generator probe temp dir"
  chmod 0700 "$tmp_dir" || failure="could not harden LLM provider eval generator probe temp dir"
  output_file="$tmp_dir/provider-run.json"
  raw_output_dir="$tmp_dir/raw"
  stdout_file="$tmp_dir/stdout.txt"
  artifacts_file="$tmp_dir/artifacts.txt"
  run_id="provider-generator-${tmp_dir##*.}"
  secret_value="sk-sourcelensProviderProbeSecret000000"

  cleanup_llm_provider_eval_probe() {
    rm -rf "$tmp_dir"
  }

  if [[ -z "$failure" ]]; then
    set +e
    run_with_timeout "node:scripts/run-llm-provider-eval.mjs" "$SECURITY_REGRESSION_NODE_TIMEOUT_SECONDS" -- \
      env -i \
      PATH="${PATH:-/usr/bin:/bin:/usr/sbin:/sbin}" \
      HOME="${HOME:-$tmp_dir}" \
      SOURCELENS_LLM_PROVIDER_EVAL_PROVIDER="security-regression-provider" \
      SOURCELENS_LLM_PROVIDER_EVAL_MODEL="security-regression-model" \
      SOURCELENS_LLM_PROVIDER_EVAL_API_KEY="$secret_value" \
      SOURCELENS_LLM_PROVIDER_EVAL_BASE_URL="http://127.0.0.1:9/v1" \
      SOURCELENS_LLM_PROVIDER_EVAL_RELEASE_RUN_ID="$run_id" \
      SOURCELENS_LLM_PROVIDER_EVAL_OUTPUT_FILE="$output_file" \
      SOURCELENS_LLM_PROVIDER_EVAL_RAW_OUTPUT_DIR="$raw_output_dir" \
      node scripts/run-llm-provider-eval.mjs > "$stdout_file" 2>&1
    exit_code=$?
    set -e
    if [[ "$exit_code" != "2" ]]; then
      cat "$stdout_file" >&2
      failure="LLM provider eval generator probe must write failed evidence and exit 2 when provider calls fail"
    fi
  fi
  if [[ -z "$failure" && ! -s "$output_file" ]]; then
    cat "$stdout_file" >&2
    failure="LLM provider eval generator must write a provider run JSON file even when provider calls fail"
  fi
  if [[ -z "$failure" ]]; then
    if rg -F -q "$secret_value" "$tmp_dir"; then
      rg -F -n "$secret_value" "$tmp_dir" >&2 || true
      failure="LLM provider eval generator must not write API keys into provider run output, raw artifacts, or logs"
    fi
  fi
  if [[ -z "$failure" ]]; then
    if ! run_security_node scripts/validate-llm-provider-run.mjs \
      "$output_file" \
      docs/llm-safety-evals/prompt-injection-cases.json \
      docs/llm-safety-evals/output-quality-cases.json \
      --run-id "$run_id" \
      --print-artifacts > "$artifacts_file" 2>> "$stdout_file"; then
      cat "$stdout_file" >&2
      failure="LLM provider eval generator output must pass provider run schema validation"
    fi
  fi
  if [[ -z "$failure" ]]; then
    while IFS= read -r artifact_path; do
      [[ -n "$artifact_path" ]] || continue
      relative_path="${artifact_path#release-evidence/${run_id}/}"
      if [[ "$relative_path" == "$artifact_path" || "$relative_path" != llm-evals/* ]]; then
        cat "$artifacts_file" >&2
        failure="LLM provider eval generator rawOutputArtifact paths must mirror release-evidence/<run-id>/llm-evals"
        break
      fi
      if [[ ! -s "$raw_output_dir/$relative_path" ]]; then
        failure="LLM provider eval generator must write matching raw output artifact: $relative_path"
        break
      fi
    done < "$artifacts_file"
  fi

  cleanup_llm_provider_eval_probe
  [[ -z "$failure" ]] || fail "$failure"
}

assert_no_match() {
  local description="$1"
  local pattern="$2"
  shift 2
  local output
  security_assert_progress "$description"
  if output="$(rg -n --hidden --glob '!backend-spring/target/**' --glob '!web-console/dist/**' -- "$pattern" "$@" 2>/dev/null)"; then
    echo "$output" >&2
    fail "$description"
  fi
}

assert_match() {
  local description="$1"
  local pattern="$2"
  shift 2
  security_assert_progress "$description"
  rg -n --hidden --glob '!backend-spring/target/**' --glob '!web-console/dist/**' -- "$pattern" "$@" >/dev/null \
    || fail "$description"
}

assert_release_evidence_loopback_runtime_guard_runs_before_init_output() {
  awk '
    /^validate_loopback_backend_runtime_boundary$/ { guard = NR }
    /^init_output$/ { init = NR }
    END { exit !(guard && init && guard < init) }
  ' scripts/release-evidence.sh \
    || fail "release evidence loopback runtime guard must run before evidence output initialization"
}

assert_match_count() {
  local description="$1"
  local expected="$2"
  local pattern="$3"
  shift 3
  local count
  security_assert_progress "$description"
  count="$(rg -n --hidden --glob '!backend-spring/target/**' --glob '!web-console/dist/**' -- "$pattern" "$@" 2>/dev/null \
    | wc -l | tr -d '[:space:]')"
  [[ "$count" == "$expected" ]] || fail "$description (expected $expected, got $count)"
}

assert_line_order() {
  local description="$1"
  local first_pattern="$2"
  local second_pattern="$3"
  local file="$4"
  security_assert_progress "$description"
  awk -v first="$first_pattern" -v second="$second_pattern" '
    $0 ~ first && first_line == 0 {
      first_line = NR
    }
    $0 ~ second && second_line == 0 {
      second_line = NR
    }
    END {
      exit(first_line > 0 && second_line > 0 && first_line < second_line ? 0 : 1)
    }
  ' "$file" || fail "$description"
}

assert_executable() {
  local path="$1"
  [[ -x "$path" ]] || fail "$path must be executable because Makefile/CI run it directly"
}

assert_generated_artifacts_inventory_group() {
  local tmp_dir
  local output_file
  local expected_path
  local probe_root
  local probe_suffix
  local probe_dir
  local probe_dirs
  local created_probe_dirs=()
  local probe_paths
  local failure=""

  tmp_dir="$(mktemp -d "${TMPDIR:-/tmp}/sourcelens-generated-artifact-inventory.XXXXXX")" \
    || fail "could not create generated artifact inventory temp dir"
  output_file="$tmp_dir/inventory.txt"
  probe_suffix="${tmp_dir##*/}"
  probe_root=".sourcelens-generated-artifact-probe-${probe_suffix}"
  probe_paths=(
    "$probe_root/.DS_Store"
    "backend-spring/target 2/.sourcelens-generated-artifact-probe-${probe_suffix}.txt"
    "analyzer-rust/target/.sourcelens-generated-artifact-probe-${probe_suffix}.txt"
    "bin/.sourcelens-generated-artifact-probe-${probe_suffix}.txt"
    "web-console/.vite/.sourcelens-generated-artifact-probe-${probe_suffix}.txt"
    "web-console/node_modules/.vite/.sourcelens-generated-artifact-probe-${probe_suffix}.txt"
  )
  probe_dirs=(
    "$probe_root"
    "backend-spring/target 2"
    "analyzer-rust/target"
    "bin"
    "web-console/.vite"
    "web-console/node_modules"
    "web-console/node_modules/.vite"
  )

  cleanup_generated_artifact_probe() {
    local index
    local probe_path
    for probe_path in "${probe_paths[@]}"; do
      rm -f "$probe_path"
    done
    for (( index=${#created_probe_dirs[@]} - 1; index >= 0; index-- )); do
      rmdir "${created_probe_dirs[$index]}" 2>/dev/null || true
    done
  }

  cleanup_generated_artifact_inventory() {
    cleanup_generated_artifact_probe
    rm -rf "$tmp_dir"
  }

  cleanup_generated_artifact_probe
  for probe_dir in "${probe_dirs[@]}"; do
    if [[ ! -d "$probe_dir" ]]; then
      created_probe_dirs+=("$probe_dir")
    fi
  done
  mkdir -p "${probe_dirs[@]}"
  for expected_path in "${probe_paths[@]}"; do
    if [[ -e "$expected_path" ]]; then
      failure="generated artifact probe path already exists: $expected_path"
      break
    fi
    printf 'probe\n' > "$expected_path"
  done

  if [[ -z "$failure" ]]; then
    cp .git/index "$tmp_dir/index" || failure="could not copy git index for generated artifact inventory check"
  fi
  if [[ -z "$failure" ]]; then
    GIT_INDEX_FILE="$tmp_dir/index" git add -f "${probe_paths[@]}" \
      || failure="could not stage generated artifact probes in temporary git index"
  fi
  if [[ -z "$failure" ]]; then
    GIT_INDEX_FILE="$tmp_dir/index" ./scripts/worktree-inventory.sh repository-hygiene-generated-artifacts > "$output_file" \
      || failure="worktree inventory repository hygiene group must run for generated artifact probes"
  fi
  if [[ -z "$failure" ]]; then
    for expected_path in "${probe_paths[@]}"; do
      if ! rg -F -q -- "$expected_path" "$output_file"; then
        cat "$output_file" >&2
        failure="worktree inventory must put generated artifact probe in repository hygiene group: $expected_path"
        break
      fi
    done
  fi

  cleanup_generated_artifact_inventory
  [[ -z "$failure" ]] || fail "$failure"
}

