      cat "$verify_output_file" >&2
      failure="untampered required smoke release evidence package must pass verifier before required-skip probe"
    fi
  fi
  if [[ -z "$failure" ]]; then
    if ! awk -F '\t' '
      BEGIN {
        OFS = "\t"
      }
      NR == 1 {
        print
        next
      }
      $2 == "smoke" && !changed {
        $1 = "SKIP"
        $3 = "-"
        $5 = "SOURCELENS_BASE_URL is not configured"
        changed = 1
      }
      {
        print
      }
      END {
        exit(changed ? 0 : 1)
      }
    ' "$run_dir/status.tsv" > "$tampered_status_file"; then
      failure="could not forge required smoke status as SKIP"
    fi
  fi
  if [[ -z "$failure" ]]; then
    if ! awk '
      /^- FAIL `smoke`: / && !changed {
        print "- SKIP `smoke`: Smoke test (SOURCELENS_BASE_URL is not configured)"
        changed = 1
        next
      }
      /^- required_failures: `/ {
        line = $0
        sub(/^- required_failures: `/, "", line)
        sub(/`[[:space:]]*$/, "", line)
        print "- required_failures: `" line - 1 "`"
        next
      }
      /^- skipped: `/ {
        line = $0
        sub(/^- skipped: `/, "", line)
        sub(/`[[:space:]]*$/, "", line)
        print "- skipped: `" line + 1 "`"
        next
      }
      {
        print
      }
      END {
        exit(changed ? 0 : 1)
      }
    ' "$run_dir/summary.md" > "$tampered_summary_file"; then
      failure="could not forge required smoke summary as SKIP"
    fi
  fi
  if [[ -z "$failure" ]]; then
    mv "$tampered_status_file" "$run_dir/status.tsv" \
      || failure="could not replace status table with forged required-skip row"
  fi
  if [[ -z "$failure" ]]; then
    mv "$tampered_summary_file" "$run_dir/summary.md" \
      || failure="could not replace summary with forged required-skip row"
  fi
  if [[ -z "$failure" ]]; then
    chmod 600 "$run_dir/status.tsv" "$run_dir/summary.md" \
      || failure="could not keep required-skip files private"
  fi
  if [[ -z "$failure" ]]; then
    rewrite_release_evidence_checksums_for_probe "$run_dir"
  fi
  if [[ -z "$failure" ]]; then
    if run_verify_release_evidence "$run_dir" > "$required_skip_output_file" 2>&1; then
      cat "$required_skip_output_file" >&2
      failure="release evidence verifier must reject required include rows forged as SKIP after checksums are regenerated"
    elif ! rg -q 'release evidence manifest include_smoke=true requires smoke status not to be SKIP' "$required_skip_output_file"; then
      cat "$required_skip_output_file" >&2
      failure="release evidence verifier must explain required include cannot be forged as SKIP"
    fi
  fi

  cleanup_release_required_skip_probe
  [[ -z "$failure" ]] || fail "$failure"
}

