        next
      }
      $2 == "worktree-inventory" && !changed {
        $1 = "SKIP"
        $3 = "-"
        $5 = "worktree inventory skipped"
        changed = 1
      }
      {
        print
      }
      END {
        exit(changed ? 0 : 1)
      }
    ' "$run_dir/status.tsv" > "$tampered_status_file"; then
