check_shell_scripts() {
  local script
  for script in scripts/*.sh; do
    bash -n "$script" || fail "$script has invalid shell syntax"
  done
}

assert_ci_job_timeout() {
  local job="$1"
  awk -v job="$job" '
    $0 == "  " job ":" {
      in_job = 1
      seen_job = 1
      next
    }
    in_job && $0 ~ /^  [A-Za-z0-9_-]+:/ {
      in_job = 0
    }
    in_job && $0 ~ /^[[:space:]]+timeout-minutes:[[:space:]]*[1-9][0-9]*[[:space:]]*$/ {
      found = 1
    }
    END {
      exit(seen_job && found ? 0 : 1)
    }
  ' .github/workflows/ci.yml || fail "CI job $job must set timeout-minutes"
}

assert_ci_checkout_steps_disable_credentials() {
  awk '
    function finish_step() {
      if (in_step && checkout_step && !persist_credentials_false) {
        print FILENAME ":" checkout_line ": checkout step must set persist-credentials: false"
        bad = 1
      }
    }
    /^[[:space:]]*-[[:space:]]/ {
      finish_step()
      in_step = 1
      checkout_step = 0
      persist_credentials_false = 0
      checkout_line = 0
    }
    in_step && /^[[:space:]]+uses:[[:space:]]*["'\'']?actions\/checkout@[0-9a-f]{40}/ {
      checkout_step = 1
      checkout_line = NR
      seen_checkout += 1
    }
    in_step && /^[[:space:]]+persist-credentials:[[:space:]]*false[[:space:]]*$/ {
      persist_credentials_false = 1
    }
    END {
      finish_step()
      if (seen_checkout == 0) {
        print FILENAME ": no checkout steps found"
        bad = 1
      }
      exit(bad ? 1 : 0)
    }
  ' .github/workflows/ci.yml || fail "every CI checkout step must set persist-credentials: false"
}

assert_ci_permissions_are_read_only() {
  awk '
    /^[[:space:]]+permissions:[[:space:]]*/ {
      print FILENAME ":" FNR ": job-level permissions blocks are not allowed"
      bad = 1
    }
    /^permissions:[[:space:]]*$/ {
      in_permissions = 1
      seen_permissions = 1
      next
    }
    in_permissions && /^[^[:space:]#][^:]*:/ {
      in_permissions = 0
    }
    in_permissions {
      line = $0
      sub(/[[:space:]]+#.*$/, "", line)
      if (line ~ /^[[:space:]]*$/) {
        next
      }
      if (line ~ /^  contents:[[:space:]]*read[[:space:]]*$/) {
        seen_contents_read = 1
        next
      }
      if (line ~ /^  [A-Za-z0-9_-]+:[[:space:]]*/) {
        print FILENAME ":" FNR ": CI permissions must grant only contents: read"
        bad = 1
      }
    }
    END {
      if (!seen_permissions) {
        print FILENAME ": top-level permissions block is required"
        bad = 1
      }
      if (!seen_contents_read) {
        print FILENAME ": top-level permissions block must include contents: read"
        bad = 1
      }
      exit(bad ? 1 : 0)
    }
  ' .github/workflows/ci.yml || fail "CI workflow permissions must grant only contents: read"
}

