for pattern in \
  'summary must contain exactly one non-empty \$key metadata value' \
  'manifest must contain exactly one non-empty \$key metadata value' \
  'must be UTC ISO-8601 seconds' \
  'must be a valid UTC ISO-8601 timestamp' \
  'summary created_at must match manifest created_at' \
  'must be a 1-64 character safe release evidence run id' \
  'summary run_id must match manifest run_id' \
  'directory basename must match manifest run_id' \
  'release evidence summary env_file' \
  'release evidence manifest root_dir' \
  'release evidence manifest env_file' \
  'release evidence summary evidence_dir' \
  'release evidence manifest llm_provider_run_file' \
  'release evidence manifest llm_raw_output_dir' \
  'must not contain control characters or backticks' \
  'summary env_file must match manifest env_file' \
  'summary evidence_dir basename must match run_id' \
  'manifest git_head must be a 40-character lowercase SHA-1 or unavailable' \
  'git-metadata status must be OK' \
  'worktree-inventory status must not be SKIP' \
  'strict OK must not contain Other paths' \
  'strict OK must not contain strict failure marker' \
  'strict FAIL must contain Other paths and strict failure marker' \
  'require_no_control_chars "\$git_status_file" "release evidence git status snapshot"' \
  'require_no_control_chars "\$git_diff_stat_file" "release evidence git diff stat snapshot"' \
  'require_no_control_chars "\$worktree_inventory_file" "release evidence worktree inventory"' \
  'release evidence manifest include_smoke' \
  'release evidence manifest worktree_inventory_strict' \
  'requires \$slug status not to be SKIP' \
  'requires \$slug status to be SKIP' \
  'requires \$slug status to be OK or FAIL' \
  'requires \$slug detail to be:' \
  'requires \$slug status to be OK, FAIL, or SKIP' \
  'worktree_inventory_strict=true requires worktree-inventory status not to be WARN' \
  'manifest file must match the generated layout exactly'
do
  assert_match \
    "release evidence verification script must enforce metadata consistency: $pattern" \
    "$pattern" \
    scripts/verify-release-evidence.sh
done

