for pattern in \
  'git-metadata must reference manifest\.txt' \
  'worktree-inventory must reference worktree-inventory\.md' \
  'make-verify must reference make-verify\.log' \
  'prod-preflight must reference prod-preflight\.log' \
  'backup-preflight must reference backup-preflight\.log' \
  'rollback-preflight must reference rollback-preflight\.log' \
  'backup-restore-drill-evidence must reference backup-restore-drill-evidence\.log or backup-restore-drill-evidence\.txt' \
  'rollback-plan must reference rollback-plan\.log or rollback-plan\.txt' \
  'smoke must reference smoke\.log' \
  'phase12-baseline must reference phase12-baseline\.log' \
  'sandbox-drill must reference sandbox-drill\.log' \
  'github-app-drill must reference github-app-drill\.log' \
  'github-webhook-drill must reference github-webhook-drill\.log' \
  'llm-provider-run must reference llm-provider-run\.log'
do
