  || fail "could not create worktree inventory strict mode output temp file"
if SOURCELENS_WORKTREE_INVENTORY_STRICT=maybe ./scripts/worktree-inventory.sh > "$worktree_strict_output" 2>&1; then
  cat "$worktree_strict_output" >&2
  rm -f "$worktree_strict_output"
  fail "worktree inventory must reject invalid strict mode values"
elif ! rg -q 'SOURCELENS_WORKTREE_INVENTORY_STRICT must be true or false' "$worktree_strict_output"; then
  cat "$worktree_strict_output" >&2
  rm -f "$worktree_strict_output"
  fail "worktree inventory must explain invalid strict mode values"
fi
rm -f "$worktree_strict_output"

assert_invalid_bool_mode_rejected() {
  local description="$1"
  local key="$2"
  local script="$3"
  local output
  output="$(mktemp "${TMPDIR:-/tmp}/sourcelens-bool-mode.XXXXXX")" \
    || fail "could not create bool mode output temp file"
  if env "$key=maybe" "$script" > "$output" 2>&1; then
    cat "$output" >&2
    rm -f "$output"
    fail "$description"
  elif ! rg -q "$key must be true or false" "$output"; then
    cat "$output" >&2
    rm -f "$output"
    fail "$description must explain invalid values"
  fi
  rm -f "$output"
}

