  fail "rollback preflight must reject enabled AutoRepair stop-switch values"
elif ! rg -q 'SOURCELENS_AUTOREPAIR_SUBMIT_PR_ENABLED must be false or unset during rollback' "$rollback_autorepair_pr_output"; then
  cat "$rollback_autorepair_pr_output" >&2
  rm -f "$rollback_autorepair_pr_output"
  fail "rollback preflight must explain enabled AutoRepair stop-switch values"
fi
rm -f "$rollback_autorepair_pr_output"

rollback_base_url_output="$(mktemp "${TMPDIR:-/tmp}/sourcelens-base-url-shape.XXXXXX")" \
  || fail "could not create rollback base URL output temp file"
if SOURCELENS_ROLLBACK_PREFLIGHT_ENV_FILE=/tmp/sourcelens-rollback-preflight-missing.env \
